/**
 * Face patch anchors, generated by scripts/process_day2_ladder_art.py and
 * scripts/process_day3_ghost_arts.py.
 *
 * Box = (x, y, w, h) in plate pixels (1024x1526) where the canonical emotion/blink patch
 * content lands on THAT plate. Day 1 stages and Day 2 stage 0 use the authored box;
 * the leaning Day 2 stages get their head measured, so blush/blink never sit on her
 * neck or float off her cheek when she moves closer to the webcam.
 */

export interface FaceAnchor {
  readonly x: number;
  readonly y: number;
  readonly w: number;
  readonly h: number;
}

export const CANONICAL_FACE: FaceAnchor = { x: 338, y: 61, w: 348, h: 397 };

/** Keyed by plate file name (as shipped in public/art). */
export const FACE_ANCHORS: Record<string, FaceAnchor> = {
  // Day 3 is four separately drawn frames now, and each one paints its own expression (a wink at
  // the finale, an open-mouth «Бу!», a smirk through the eye holes). The face is also ~1.4x the
  // canonical scale there, so an overlay authored for the Day 1 face would land on her cheekbone
  // or her neck. Every Day 3 plate is therefore in FACE_PATCH_COVERED_PLATES below, and these
  // boxes are the measured faces, kept for the debug overlay only.
  // s0/s1 were re-measured after their raws were re-framed for the desk (t3_dsk_a1/a2): the face
  // band here is the skin visible through the torn eye holes, rows 120-520 only.
  "heroine_t3_s0.webp": { x: 413, y: 208, w: 224, h: 300 },
  "heroine_t3_s1.webp": { x: 396, y: 200, w: 240, h: 300 },
  "heroine_t3_s2.webp": { x: 560, y: 208, w: 300, h: 260 },
  "heroine_t3_s3.webp": { x: 408, y: 176, w: 368, h: 300 },
  "heroine_t3_s4.webp": { x: 396, y: 176, w: 396, h: 288 },
  "heroine_t3_flash.webp": { x: 408, y: 176, w: 368, h: 300 },
  "heroine_t2_s0.webp": { x: 336, y: 60, w: 347, h: 395 },
  "heroine_t2_s1.webp": { x: 336, y: 60, w: 347, h: 395 },
  "heroine_t2_s2.webp": { x: 336, y: 60, w: 347, h: 395 },
  "heroine_t2_s3.webp": { x: 313, y: 43, w: 382, h: 435 },
  "heroine_t2_s4.webp": { x: 336, y: 57, w: 362, h: 411 },
  "heroine_t1_s0.webp": { x: 338, y: 61, w: 348, h: 397 },
  "heroine_t1_s1.webp": { x: 338, y: 61, w: 348, h: 397 },
  "heroine_t1_s2.webp": { x: 338, y: 61, w: 348, h: 397 },
  "heroine_t1_s3.webp": { x: 338, y: 61, w: 348, h: 397 },
  "heroine_t1_s4.webp": { x: 338, y: 61, w: 348, h: 397 },
};

export function faceAnchorFor(plateUrl: string): FaceAnchor {
  const name = plateUrl.split('/').pop() ?? '';
  return FACE_ANCHORS[name] ?? CANONICAL_FACE;
}

/** Plates whose face hides under a costume layer: emotion/blink patches must stay off. */
export const FACE_PATCH_COVERED_PLATES: ReadonlySet<string> = new Set([
  "heroine_t3_s0.webp",
  "heroine_t3_s1.webp",
  "heroine_t3_s2.webp",
  "heroine_t3_s3.webp",
  "heroine_t3_s4.webp",
  "heroine_t3_flash.webp",
]);
